class Frame:
    def __init__(self, rows):
        self.rows = rows
    def drop_duplicates(self, subset):
        key = subset[0]
        seen = set()
        result = []
        for row in self.rows:
            if row[key] in seen:
                continue
            seen.add(row[key])
            result.append(row)
        return result

frame = Frame([{"id": 1, "name": "A"}, {"id": 1, "name": "B"}, {"id": 2, "name": "C"}])
deduped = frame.drop_duplicates(subset=["id"])

