class Table:
    def __init__(self, rows):
        self.rows = rows
    def groupby(self, field):
        result = {}
        for row in self.rows:
            result.setdefault(row[field], []).append(row)
        return result

table = Table([{"status": "PASS"}, {"status": "FAIL"}, {"status": "PASS"}])
groups = table.groupby("status")

