issues = []

def check_schema(dataset):
    if any("id" not in row for row in dataset):
        issues.append("schema")

def check_duplicates(dataset):
    ids = [row["id"] for row in dataset]
    if len(ids) != len(set(ids)):
        issues.append("duplicate")

dataset = [{"id": "d1"}, {"id": "d2"}, {"id": "d2"}]
validators = [check_schema, check_duplicates]
for validate in validators:
    validate(dataset)
audit = list(issues)
accepted = not issues
print(issues, audit, accepted)
